INSERT INTO `document_types` (`id`, `code`, `name`, `description`, `is_active`, `created_at`, `updated_at`) VALUES
('01a13ec1-3768-7372-9783-b203a65b6e27', 'SKTM', 'Surat Keterangan Tidak Mampu', 'Surat bukti prasejahtera untuk beasiswa, bantuan sosial, atau keringanan biaya pengobatan. Syarat: KTP, KK, Surat Pengantar RT/RW. Prosedur: Pengajuan via web/kantor desa -> Verifikasi Staf -> Persetujuan Kepala Desa -> Cetak PDF. Biaya: Gratis (Rp 0). Estimasi waktu: 1-2 hari kerja.', 1, '2026-10-15 01:50:12', '2026-11-12 06:42:38'),
('01a13ec1-3770-704f-a3d9-b67019b01438', 'SK_DOMISILI', 'Surat Keterangan Domisili', 'Surat menerangkan tempat tinggal / domisili warga di wilayah desa. Syarat: KTP, KK, Surat Pengantar RT/RW, Surat pernyataan tempat tinggal jika sewa. Biaya: Gratis (Rp 0). Estimasi waktu: 1 hari kerja.', 1, '2026-10-15 01:50:12', '2026-10-15 01:50:12'),
('01a13ec1-3777-7276-88e0-6e57632d8d02', 'PENGANTAR_SKCK', 'Surat Pengantar SKCK', 'Surat pengantar desa untuk pembuatan SKCK di Polsek/Polres. Syarat: Fotokopi KTP, KK, Surat Pengantar RT/RW, Pasfoto 4x6 (2 lembar). Catatan: SKCK resmi diterbitkan Polsek/Polres. Biaya di desa: Gratis (Rp 0).', 1, '2026-10-15 01:50:12', '2026-10-15 01:50:12'),
('01a13ec1-377e-706c-81e8-91508b93171f', 'SKU', 'Surat Keterangan Usaha', 'Surat keterangan memiliki usaha di lokasi desa. Syarat: KTP, KK, Surat Pengantar RT/RW, Foto tempat usaha. Biaya: Gratis (Rp 0). Estimasi waktu: 1-2 hari kerja.', 1, '2026-10-15 01:50:12', '2026-10-15 01:50:12'),
('01a13ec1-3785-7371-bcff-0fb5fdacd5a6', 'SK_KELAHIRAN', 'Surat Keterangan Kelahiran', 'Surat pengantar untuk penerbitan Akta Kelahiran di Disdukcapil. Syarat: Surat Lahir Bidan/RS, KTP Orang Tua, KK, Buku Nikah. Biaya: Gratis (Rp 0).', 1, '2026-10-15 01:50:12', '2026-10-15 01:50:12');
